const srcById=new Map(archive.sources.map(s=>[s.id,s]));
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const coursePage=id=>id===1?'lesson':'course-'+id;
const cLink=id=>href(coursePage(id));
const chapterById=id=>archive.chapters.find(c=>c.number===id);
const statusNames={confirmed:'已确认',experimental:'实验中',inference:'推断',planned:'计划中',unknown:'未知'};
const tagNames={github:'GitHub',community:'Community · GitHub standup',metrics:'W&B / 报告',twitter:'X / Twitter'};
function hashText(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function relateEvent(update){const txt=(update.title.zh+' '+update.detail.zh).toLowerCase();const rules=[[/mixture|data mix|数据配|数据混/,5],[/scaling|ladder|rung|扩展律/,6],[/checkpoint|restore|recovery|oom|恢复|存档/,12],[/mfu|throughput|goodput|gc |garbage|吞吐/,11],[/all-to-all|ragged|nvlink|nccl|rack|通信/,10],[/context|65k|262k|上下文/,15],[/eval|bpb|benchmark|评测/,14],[/router|expert|moe|专家/,8],[/gradient|loss|norm|梯度/,13],[/optimizer|learning.rate|weight decay/,9]];return rules.filter(([re])=>re.test(txt)).slice(0,3).map(([,id])=>id)}
const events=archive.updates.map(u=>{const sourceItems=u.sourceIds.map(id=>srcById.get(id)).filter(Boolean);const tags=new Set();for(const s of sourceItems){if(s.url.includes('github.com'))tags.add('github');if(s.kind==='standup')tags.add('community');if(s.url.includes('wandb.ai')||s.kind==='report')tags.add('metrics');if(/^https?:\/\/(www\.)?(twitter|x)\.com/.test(s.url))tags.add('twitter')}const related=relateEvent(u);return {...u,key:'event-'+u.date+'-'+hashText(u.title.zh),sourceItems,tags:[...tags],courseIds:related.length?related:[18]}});
let timelineState={channel:'all',status:'all',course:'all',query:'',limit:12};
function chapterLinks(course){return course.chapters.map(n=>{const c=chapterById(n);return `<a class="chapter-list-link" href="${href('chapter-'+n)}" data-go="chapter-${n}"><span>CH ${String(n).padStart(2,'0')}</span>${esc(c.title)}<span>↗</span></a>`}).join('')}
function integratedMaterials(id){const c=courses.find(c=>c.id===id);return `<section class="embedded-chapters"><div class="eyebrow">ONE CURRICULUM / FROM INTUITION TO EVIDENCE</div><h3 style="margin-top:12px">这一课的 Marin 深入材料</h3><p>先理解上面的直觉，再按需要阅读原教材。章节已经接入当前课程，可直接打开全文。</p>${chapterLinks(c)}${marinResourceGuide(id)}${c.supplement?`<div class="archive-banner">${esc(c.supplement)}</div>`:''}<a class="timeline-course-link" href="${href('timeline')}" data-course-timeline="${id}">看看这个知识点在真实训练中怎样出现 →</a></section>`}
function courseOutline(){return `<main class="container"><section class="curriculum-intro"><div class="eyebrow">ONE CONNECTED LEARNING PATH</div><h1>18 节课，读懂同一个训练过程。</h1><p>把 Marin 的 38 章内容融进同一条学习路径。先用图解建立直觉，再读真实案例与技术细节；最新进展会把你带回对应的知识点。</p><div class="curriculum-stats"><div><strong>18</strong><span>节主课</span></div><div><strong>38</strong><span>章原教材已接入</span></div><div><strong>83</strong><span>条已有进展</span></div></div><div class="curriculum-links"><a data-go="timeline" href="${href('timeline')}">历史训练记录 ↗</a><a href="/marin-original.md" download>下载保留的原教材 Markdown ↗</a></div></section><div class="course-map-note">每课都有「先理解 → 看案例 → 深入原章 → 联系进展」的同一结构。第 1 课已完成互动实验；其余 17 课已接入导读、对应章节与进展，专属动画和练习仍将逐步制作。原教材历史事实保留 ${archive.snapshot} 快照边界。</div>${courseUnits.map(unit=>`<section class="module-section"><div class="module-aside"><span class="num">0${unit.id}</span><h2>${unit.title}</h2><p>${unit.goal}</p></div><div>${courses.filter(c=>c.unit===unit.id).map(c=>`<article class="course-row"><div class="course-row-top"><span class="number">${String(c.id).padStart(2,'0')}</span><h3><a href="${cLink(c.id)}" data-go="${coursePage(c.id)}">${c.title}</a></h3><button class="course-open" data-go="${coursePage(c.id)}" aria-label="打开第 ${c.id} 课">↗</button></div><p>${c.question}</p><div class="course-meta"><span class="badge ${c.id===1?'green':''}">${c.id===1?'互动示范课已完成':'导读与原章已接入'}</span><span class="badge">${c.visual}</span></div><div class="chapter-chips">${c.chapters.map(n=>`<a href="${href('chapter-'+n)}" data-go="chapter-${n}" title="${esc(chapterById(n).title)}">原教材 第 ${n} 章 ↗</a>`).join('')}</div></article>`).join('')}</div></section>`).join('')}</main>`}
function courseTopic(id){const c=courses.find(c=>c.id===id);if(!c)return courseOutline();return `<main class="container"><div class="crumb"><button data-go="learn">完整课程</button> / 单元 ${c.unit} / 第 ${c.id} 课</div><article class="course-topic"><div class="eyebrow">LESSON ${String(c.id).padStart(2,'0')} / ${courseUnits[c.unit-1].title}</div><h1 class="lesson-title">${c.title}</h1><p class="lesson-lead">${c.question}</p><p class="lesson-status-note">课程导读与 Marin 原章已接入 · 本课专属交互尚在制作</p><div class="course-path-visual">${c.path.map((t,i)=>`<div><span class="label">0${i+1} / ${['从这里开始','理解中间过程','观察结果'][i]}</span><h3>${t}</h3><p>${['先明确输入和目标。','把关键机制放回全流程。','区分已知事实与需要验证的结果。'][i]}</p></div>`).join('')}</div><div class="practice-prompt"><strong>带着这个问题读：</strong><br>${c.prompt}</div>${integratedMaterials(id)}<section class="lesson-block"><div class="block-head"><span class="block-number">LIVE CONTEXT</span><h2>这个概念，出现在这些训练记录里。</h2></div><p class="lesson-status-note">按主题匹配的推荐阅读；保留原日报日期与证据标签。</p>${relatedPreview(id)}</section><div class="next-lesson" style="margin-bottom:35px"><div><p>沿着同一条课程继续</p><h3>${id<18?courses[id].title:'去时间线，写下自己的第一条观察。'}</h3></div><button class="button primary" data-go="${id<18?coursePage(id+1):'timeline'}">${id<18?'下一课':'进入时间线'} →</button></div></article></main>`}
function chapterReader(number){const c=chapterById(number);if(!c)return courseOutline();const linked=courses.filter(x=>x.chapters.includes(number));return `<main class="container"><div class="crumb"><button data-go="learn">课程</button> / Marin 深入阅读 / 第 ${number} 章</div><div class="chapter-reader"><aside><h3>这章属于哪些课程？</h3>${linked.map(x=>`<a href="${cLink(x.id)}" data-go="${coursePage(x.id)}">第 ${x.id} 课 · ${x.title} →</a>`).join('')}<a data-go="learn" href="${href('learn')}">查看完整 18 课纲要 ↗</a><a data-go="timeline" href="${href('timeline')}">历史训练记录 ↗</a></aside><article class="chapter-content"><div class="eyebrow">MARIN FIELD NOTES / CHAPTER ${number}</div><h1>${esc(c.title)}</h1><div class="archive-banner">原教材历史快照 · ${archive.snapshot}。保留原文与引用，本次接入没有重新核验所有上游状态；“当前”“计划中”等表述均以快照日期为准。</div><div class="chapter-prose">${c.html}</div><section class="embedded-chapters"><h3>回到你的学习主线</h3><p>把刚读到的技术细节，放回概念与真实进展。</p>${linked.map(x=>`<a class="chapter-list-link" data-go="${coursePage(x.id)}" href="${cLink(x.id)}"><span>LESSON ${x.id}</span>${x.title}<span>→</span></a>`).join('')}</section></article></div></main>`}
function eventCard(e,compact=false){const first=courses.find(c=>c.id===e.courseIds[0]);return `<article class="event-card" id="${e.key}"><div class="event-tags"><span class="badge ${e.status==='confirmed'?'green':e.status==='planned'?'orange-text':''}">原记录：${statusNames[e.status]||esc(e.status)}</span>${e.tags.map(t=>`<span class="source-tag">${tagNames[t]}</span>`).join('')}</div><h3>${esc(e.title.zh)}</h3><p class="audit-label">${e.date} · 历史整理记录，未逐条独立复核${e.sourceIds.includes('M100')?' · Live W&B 数字待复核':''}</p><p class="event-insight">学习切入点：${esc(first.question)}</p>${compact?'':`<details><summary>展开原始研究摘要与数字</summary><p>${esc(e.detail.zh)}</p></details><div class="event-sources">${e.sourceItems.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" title="${esc(s.title)}">${s.id} · ${s.kind==='standup'?'社区 standup':s.kind==='pr'?'PR':s.kind==='issue'?'Issue':'报告 / 指标'} ↗</a>`).join('')}</div>`}<a class="event-course" href="${cLink(first.id)}" data-go="${coursePage(first.id)}"><span>关联课程</span>第 ${first.id} 课 · ${first.title} <b style="margin-left:auto;font-weight:400">→</b></a>${compact?`<a class="timeline-course-link" href="${href('timeline')}#${e.key}" data-event-open="${e.key}">查看 ${e.date} 原记录与来源 ↗</a>`:''}</article>`}
function relatedPreview(id){const chosen=events.filter(e=>e.courseIds.includes(id)).slice(0,2);return chosen.length?chosen.map(e=>eventCard(e,true)).join(''):`<div class="empty-timeline"><p>已有快照中暂未匹配到这一课的专门更新。可以先读对应原章，或进入全部时间线练习辨认训练阶段。</p><button class="text-button" data-go="timeline">查看全部记录 →</button></div>`}
function timelineFiltered(){const q=timelineState.query.trim().toLowerCase();return events.filter(e=>(timelineState.channel==='all'||e.tags.includes(timelineState.channel))&&(timelineState.status==='all'||e.status===timelineState.status)&&(timelineState.course==='all'||e.courseIds.includes(Number(timelineState.course)))&&(!q||(e.title.zh+' '+e.detail.zh+' '+e.sourceItems.map(s=>s.title).join(' ')).toLowerCase().includes(q)))}
function timelineResults(){const filtered=timelineFiltered(),shown=filtered.slice(0,timelineState.limit);if(!filtered.length)return `<div class="empty-timeline"><h3>${timelineState.channel==='twitter'?'已确定 4 位关注对象，帖子待导入':'没有匹配到记录'}</h3><p>${timelineState.channel==='twitter'?'关注名单与主题由你提供；当前尚未导入这四位的帖子，也未启用自动采集。下方可直接访问账号。':'试着调整来源、状态、课程或关键词；资料缺失不代表项目没有发生变化。'}</p>${timelineState.channel==='twitter'?xWatchlistHtml():''}<button class="text-button" data-reset-timeline>回到全部记录 →</button></div>`;const days=new Map();for(const e of shown){if(!days.has(e.date))days.set(e.date,[]);days.get(e.date).push(e)}return [...days].map(([date,items])=>`<section class="timeline-day"><div class="timeline-date"><time>${date}</time><small>日报日期 · ${items.length} 条</small></div><div class="timeline-entries">${items.map(e=>eventCard(e)).join('')}</div></section>`).join('')+(shown.length<filtered.length?`<div class="load-more"><button class="button" data-load-timeline>继续看更早记录 · ${shown.length} / ${filtered.length} ↓</button></div>`:'<div class="results-caption">已显示当前筛选下的全部历史记录。</div>')}
function timeline(){return `<main class="container"><section class="timeline-header"><div><div class="eyebrow">THE TRAINING JOURNAL / DAILY PROGRESS</div><h1>训练记录：带着问题，回看真实过程。</h1><p>把代码、社区讨论与实验记录连成一条学习线索。遇到不熟悉的概念，直接回到对应课程，再继续观察。</p></div><div class="timeline-stats"><div><strong>${events.length}</strong><span>已有更新</span></div><div><strong>${new Set(events.map(e=>e.date)).size}</strong><span>个记录日</span></div><div><strong>${archive.sources.length}</strong><span>个来源</span></div></div></section><div class="archive-banner">资料快照截至 ${archive.snapshot} · 已导入 Solo Unicorn 现有日报，未重新逐条核验。此窗口目前展示已有记录，尚未自动抓取新的 GitHub、社区或 X 帖子。</div><div class="timeline-layout"><div><div class="timeline-tools"><div class="filter-buttons" role="group" aria-label="进展来源">${[['all','全部来源'],['github','GitHub'],['community','Community'],['metrics','W&B / 报告'],['twitter','X / Twitter · 4 位关注']].map(([key,name])=>`<button data-timeline-channel="${key}" class="${timelineState.channel===key?'active':''}" aria-pressed="${timelineState.channel===key}">${name}</button>`).join('')}</div><div class="filter-controls"><input id="timeline-search" type="search" placeholder="搜索 checkpoint、数据配比、故障…" aria-label="搜索进展" value="${esc(timelineState.query)}"><select id="timeline-status" aria-label="筛选事实状态"><option value="all">全部事实状态</option>${Object.entries(statusNames).map(([key,label])=>`<option value="${key}" ${timelineState.status===key?'selected':''}>${label}</option>`).join('')}</select><select id="timeline-course" aria-label="按关联课程筛选"><option value="all">全部关联课程</option>${courses.map(c=>`<option value="${c.id}" ${timelineState.course==c.id?'selected':''}>${String(c.id).padStart(2,'0')} · ${c.title}</option>`).join('')}</select></div><div class="results-caption" id="timeline-count">${timelineFiltered().length} 条匹配记录 · 多来源记录可以出现在多个筛选中 · 课程关联按主题匹配</div></div><div id="timeline-results">${timelineResults()}</div></div><aside class="timeline-aside"><div class="panel"><h3>来源窗口</h3><div class="channel-row"><div>GitHub<small>Issue、PR 与原始讨论</small></div><b>已导入</b></div><div class="channel-row"><div>Community<small>${archive.sources.filter(s=>s.kind==='standup').length} 份 standup，原文托管于 GitHub</small></div><b>已导入</b></div><div class="channel-row"><div>W&B / 实验报告<small>通过已有日报保存的观察</small></div><b>已有快照</b></div><div class="channel-row pending"><div>X / Twitter<small>4 位关注对象 · 0 条已导入帖子</small></div><b>待导入</b></div><details class="x-watchlist-details"><summary>查看关注人物与主题</summary>${xWatchlistHtml()}<p>名单与关注主题由你提供；账号内容尚未核验。</p></details><div class="channel-row pending"><div>其他 Community 渠道<small>Discord 等来源地址待确认</small></div><b>待确认</b></div></div><div class="panel"><h3>每天，先问三个问题。</h3><p>01 · 哪个 run 或实验发生了变化？<br>02 · 这是已部署、实验、计划还是推断？<br>03 · 它帮助我理解哪一课？</p><a class="timeline-course-link" data-go="course-18" href="${cLink(18)}">第 18 课 · 自己读一次真实训练 →</a></div><div class="panel"><h3>一次学习，两种入口。</h3><p>课程给你稳定的理解框架；进展让你看到框架如何用于真实问题。原日报的专业摘要可以按需展开。</p><a class="timeline-course-link" data-go="learn" href="${href('learn')}">返回 18 课完整路径 →</a></div></aside></div></main>`}
function homeTimeline(){return `<section class="section home-timeline">${sectionHead('The daily window','今天的进展，也能成为下一课。','已有日报快照 · '+archive.snapshot+' · 原始记录可展开并追溯',`<button class="text-button" data-go="timeline">查看完整时间线 ↗</button>`)}<div class="home-timeline-grid"><div>${events.slice(0,2).map(e=>eventCard(e,true)).join('')}</div><div class="timeline-summary"><span class="eyebrow">LEARN ↔ OBSERVE</span><h3>读到一次故障，<br>正好学懂一次恢复。</h3><p>从更新进入课程，也从课程返回真实现场。GitHub、社区 standup 和训练报告汇聚在这里；已确定 4 位 X 关注对象，具体帖子待导入。</p><div class="stats"><div><strong>18</strong><span> 节主课</span></div><div><strong>38</strong><span> 章教材</span></div><div><strong>83</strong><span> 条进展</span></div></div><button class="button primary" data-go="learn">查看融合后的课程 →</button></div></div></section>`}
function integratedSidebar(){return `<aside class="lesson-sidebar"><div class="eyebrow">ONE CONNECTED CURRICULUM</div><h3>18 课主线<br>38 章深入材料</h3><div class="integrated-side-nav">${courseUnits.map(u=>`<h4>单元 ${u.id} · ${u.title}</h4>${courses.filter(c=>c.unit===u.id).map(c=>`<a href="${cLink(c.id)}" data-go="${coursePage(c.id)}" class="${c.id===1?'active':''}"><span class="n">${String(c.id).padStart(2,'0')}</span>${c.title}</a>`).join('')}`).join('')}</div><div class="progress-track"><i style="width:${state.completed?100/18:0}%"></i></div><p class="mono muted">${state.completed?1:0} / 18 LESSONS COMPLETED</p><a class="timeline-course-link" href="${href('timeline')}" data-go="timeline">历史训练记录 ↗</a></aside>`}

const marinLearningResources=[
 {id:'deepwiki',title:'Marin DeepWiki',type:'AI 生成的代码导读',url:'https://deepwiki.com/marin-community/marin/1-overview',lessons:[2,9,10],question:'数据、训练、评测与调度分别由哪些模块负责？',guide:'先看 Overview 的结构图，再按问题进入具体模块；顺着源码引用核对实现。',boundary:'注意索引日期与代码版本；它不是官方运行状态或技术结论的最终证据。'},
 {id:'documentation',title:'Marin Documentation',type:'项目官方文档',url:'https://marin.readthedocs.io/en/latest/',lessons:[2,4,9,14,18],question:'一个最小实验如何从数据准备走到训练与评测？',guide:'先读 Language Modeling Pipeline，再按需看 First Experiment、Training Configuration 与 Run Evaluations。',boundary:'只想建立概念时无需安装或租用设备；文档配置应与实际代码版本对应。'},
 {id:'speedrun',title:'Marin Speedrun · Scaling',type:'项目交互实验看板',url:'https://marin.community/speedrun/?track=scaling&xAxis=model_flops&yAxis=absolute',lessons:[6,11,14],question:'在相同计算预算下，哪种训练配方更有效？',guide:'从 Model FLOPs × Absolute BPB 视图开始，比较曲线，再打开具体 run 的代码或 W&B 记录。',boundary:'分清实测点、拟合曲线与 projected BPB；不要把排行榜预测值当成 Hero Run 已取得的成绩。'}
];
function marinResourceGuide(courseId=null){
 const selected=marinLearningResources.filter(r=>courseId===null||r.lessons.includes(courseId));if(!selected.length)return '';
 return '<section class="marin-resource-guide"><div class="eyebrow">READ WITH A QUESTION</div><h3>带着问题，打开 Marin 的学习工具。</h3>'+selected.map(r=>`<article class="marin-resource-card" data-resource-id="${r.id}"><span class="badge">${r.type}</span><h4><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${r.title} ↗</a></h4><p class="resource-question">${r.question}</p><p>${r.guide}</p><p class="resource-boundary">阅读边界：${r.boundary}</p>${courseId===null?'<div class="chapter-chips">'+r.lessons.map(id=>`<a href="${cLink(id)}" data-go="${coursePage(id)}">第 ${id} 课 ↗</a>`).join('')+'</div>':''}</article>`).join('')+'</section>';
}
const originalResourcePage=resources;
resources=function(){return originalResourcePage().replace('</section>','</section>'+marinResourceGuide())};

const baseRender=render;
learn=courseOutline;
sidebar=integratedSidebar;
stageModal=function(i){go(coursePage([4,3,7,1,14,16][i]||2))};
render=function(){
 if(state.page==='next'){state.page='course-2';updateUrl()}
 if(state.page==='timeline'){$('#app').innerHTML=header()+timeline()+footer();switcher()}
 else if(/^course-\d+$/.test(state.page)){$('#app').innerHTML=header()+courseTopic(+state.page.split('-')[1])+footer();switcher()}
 else if(/^chapter-\d+$/.test(state.page)){$('#app').innerHTML=header()+chapterReader(+state.page.split('-')[1])+footer();switcher()}
 else {baseRender();if(state.page==='home')$('#app main').insertAdjacentHTML('beforeend',homeTimeline());if(state.page==='lesson'){
 const target=$('#case');if(target)target.insertAdjacentHTML('afterend',integratedMaterials(1));
 const next=$('.next-lesson');if(next)next.innerHTML=`<div><p id="completion-text">${state.completed?'✓ 已完成理解检查':'理解这一小步，再看看全局'}</p><h3>${courses[1].title}</h3></div><button class="button primary" data-go="course-2">下一课 →</button>`;
 const eyebrow=$('.lesson-sidebar .eyebrow');if(eyebrow)eyebrow.textContent='ONE CONNECTED CURRICULUM';
 }if(state.page==='marin'){$('.project-hero').insertAdjacentHTML('beforeend',`<div class="curriculum-links"><a href="${href('timeline')}" data-go="timeline">查看 83 条已有进展 ↗</a><a href="${href('learn')}" data-go="learn">进入 18 课 / 38 章学习路径 ↗</a></div>`);}}
 if(state.page==='marin'){const aside=$('.project-aside');if(aside)aside.insertAdjacentHTML('beforeend','<h3 style="margin-top:24px">代码、文档与实验看板</h3>'+marinLearningResources.map(r=>`<a class="source-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${r.title} ↗</a>`).join(''));}
 if(state.page==='timeline')document.title='历史训练记录 · Open Foundation Model Training';
 if(state.page.startsWith('chapter-'))document.title=(chapterById(+state.page.split('-')[1])?.title||'深入阅读')+' · Marin';
 if(state.page.startsWith('course-'))document.title=(courses.find(c=>c.id===+state.page.split('-')[1])?.title||'课程')+' · Open Foundation Model Training';
};
function refreshTimeline(){if(!$('#timeline-results'))return;$('#timeline-results').innerHTML=timelineResults();$('#timeline-count').textContent=`${timelineFiltered().length} 条匹配记录 · 多来源记录可以出现在多个筛选中 · 课程关联按主题匹配`}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.timelineChannel){timelineState.channel=el.dataset.timelineChannel;timelineState.limit=12;render()}
 else if(el.hasAttribute('data-load-timeline')){timelineState.limit+=12;refreshTimeline()}
 else if(el.hasAttribute('data-reset-timeline')){timelineState={channel:'all',status:'all',course:'all',query:'',limit:12};render()}
 else if(el.dataset.courseTimeline){e.preventDefault();timelineState={channel:'all',status:'all',course:el.dataset.courseTimeline,query:'',limit:12};go('timeline')}
 else if(el.dataset.eventOpen){e.preventDefault();timelineState={channel:'all',status:'all',course:'all',query:'',limit:events.length};go('timeline');history.replaceState(history.state,'',href('timeline')+'#'+el.dataset.eventOpen);document.getElementById(el.dataset.eventOpen)?.scrollIntoView({behavior:'smooth'})}
 else if(el.dataset.answer && state.completed){const p=$('.progress-track i');if(p)p.style.width=(100/18)+'%';const t=$('.lesson-sidebar .mono');if(t)t.textContent='1 / 18 LESSONS COMPLETED';const f=$('.footer span:last-child');if(f)f.textContent='交互原型 · 本次已完成 1 / 18 课';const m=$('.mobile-progress');if(m)m.textContent='从零看懂训练 · 已完成 1 / 18 课'}
});
document.addEventListener('input',e=>{if(e.target.id==='timeline-search'){timelineState.query=e.target.value;timelineState.limit=12;refreshTimeline()}});
document.addEventListener('change',e=>{if(e.target.id==='timeline-status'||e.target.id==='timeline-course'){timelineState[e.target.id==='timeline-status'?'status':'course']=e.target.value;timelineState.limit=12;refreshTimeline()}});
render();
if(state.page==='timeline'&&location.hash){timelineState.limit=events.length;refreshTimeline();document.getElementById(location.hash.slice(1))?.scrollIntoView()}
